  { month: 'Sep', sales: 2643 },
  { month: 'Oct', sales: 2837 },
  { month: 'Nov', sales: 2954 },
  { month: 'Dec', sales: 3239 },
];

const SalesChart = () => (
  <Card>
    <Title>Продажи за 2023 год</Title>
    <LineChart
      className="mt-6"
      data={salesData}
      index="month"
      categories={['sales']}
      colors={['blue']}
      valueFormatter={(value) => `$${value.toLocaleString()}`}
